import json, random, sys, importlib
import numpy as np
sys.path.insert(0, '/app')
import estimator

TOPICS = ['code', 'math', 'writing', 'factual']
LENGTHS = ['short', 'long']
STRATA = [t + '|' + L for t in TOPICS for L in LENGTHS]
# measured in the lab (approximate): true rate, P(j=1|h=1)=1-FNR, P(j=1|h=0)=FPR
BASE = {
    'code|short':   (0.21, 0.85, 0.02),
    'code|long':    (0.83, 0.92, 0.10),
    'math|short':   (0.41, 0.80, 0.10),
    'math|long':    (0.53, 0.95, 0.40),
    'writing|short':(0.73, 0.85, 0.05),
    'writing|long': (0.70, 0.98, 0.45),
    'factual|short':(0.32, 0.80, 0.03),
    'factual|long': (0.44, 0.95, 0.30),
}
DEV_N = {'code|long':136,'code|short':80,'factual|long':93,'factual|short':115,
         'math|long':78,'math|short':102,'writing|long':121,'writing|short':175}


class Env:
    def __init__(self, rows, truth, mix, budget=220):
        self.rows = rows; self._truth = truth; self.production_mix = mix
        self.label_budget = budget; self.topics = TOPICS; self.lengths = LENGTHS
        self.target_coverage = 0.9; self.spent = 0; self.out = None
    def label(self, ids):
        self.spent += len(ids)
        if self.spent > self.label_budget: raise RuntimeError('budget')
        return {str(i): self._truth[i] for i in ids}
    def submit(self, p, lo, hi): self.out = (p, lo, hi)


def make_arena(rng, jitter=True, target='process'):
    sizes = {s: max(30, int(rng.normal(DEV_N[s], 15))) for s in STRATA}
    params = {}
    for s in STRATA:
        t, tpr, fpr = BASE[s]
        if jitter:
            t = float(np.clip(t + rng.normal(0, 0.08), 0.03, 0.97))
            tpr = float(np.clip(tpr + rng.normal(0, 0.06), 0.5, 1.0))
            fpr = float(np.clip(fpr + rng.normal(0, 0.08), 0.0, 0.6))
        params[s] = (t, tpr, fpr)
    rows, truth = [], {}
    i = 0
    real = {}
    for s in STRATA:
        t, tpr, fpr = params[s]
        wins = 0
        for _ in range(sizes[s]):
            h = rng.random() < t
            j = rng.random() < (tpr if h else fpr)
            tp, L = s.split('|')
            rows.append({'id': i, 'topic': tp, 'length': L, 'judge_win': bool(j)})
            truth[i] = bool(h); wins += h; i += 1
        real[s] = wins / sizes[s]
    rng.shuffle(rows)
    mix = rng.dirichlet(np.ones(8) * 1.5)
    mix = {s: float(m) for s, m in zip(STRATA, mix)}
    tv_proc = sum(mix[s] * params[s][0] for s in STRATA)
    tv_real = sum(mix[s] * real[s] for s in STRATA)
    return rows, truth, mix, (tv_proc if target == 'process' else tv_real)


def run(n=400, seed=0, **kw):
    rng = np.random.default_rng(seed)
    cov = 0; widths = []; errs = []
    for _ in range(n):
        rows, truth, mix, tv = make_arena(rng, **kw)
        env = Env(rows, truth, mix)
        importlib.reload(estimator)
        estimator.estimate(env)
        p, lo, hi = env.out
        cov += lo <= tv <= hi; widths.append(hi - lo); errs.append(p - tv)
        assert env.spent <= 220
    print(kw, 'coverage', cov / n, 'mean width', np.mean(widths), 'max width', np.max(widths),
          'rmse', np.sqrt(np.mean(np.square(errs))), 'bias', np.mean(errs))

if __name__ == '__main__':
    run(target='process')
    run(target='real')
    run(jitter=False, target='process')

